coding.solution:
def use_report(metrics):
    out = []
    for name, m in metrics.items():
        if m['queue'] > m['capacity']:
            out.append((name, 'saturated'))
        if m['util'] >= 80:
            out.append((name, 'high-util'))
        if m['errors'] > 0:
            out.append((name, 'errors'))
    return sorted(out)

