coding.solution:
def knee(steps, min_gain=0.1):
    for (u0, t0), (u1, t1) in zip(steps, steps[1:]):
        gain = (t1 / t0 - 1) / (u1 / u0 - 1)
        if gain < min_gain:
            return u1
    return None
